fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    // Assumes s2.len() == n and s3.len() == n based on problem statement

    // Pre-allocate output vector to hold 3*n elements
    let mut res = Vec::with_capacity(3 * n);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}